insert into cases (industry, year, job, main_driver, supporting_drivers, stage, what_created, source, source_url, approximate) values
('banking', -2000, 'safekeeping', 'growth', array['security']::driver[], 'expansion', 'Temples and palaces in Mesopotamia stored grain and silver for others and lent against it.', 'Homer, S. & Sylla, R., A History of Interest Rates, 4th ed. (Wiley, 2005), early chapters on Mesopotamia; dating is approximate.', null, true),
('banking', -1754, 'rules and oversight', 'government', array['trust']::driver[], 'rule', 'Written laws on loans, interest limits and debt records (Code of Hammurabi).', 'Code of Hammurabi, transl. L. W. King (1910), Yale Avalon Project; date of reign is approximate.', null, true),
('banking', 1397, 'moving value', 'technology', array['growth']::driver[], 'expansion', 'Medici Bank: branch network across Europe using bills of exchange and double-entry bookkeeping.', 'de Roover, R., The Rise and Decline of the Medici Bank, 1397-1494 (Harvard University Press, 1963).', null, false),
('banking', 1694, 'lending', 'government', array['growth']::driver[], 'expansion', 'Bank of England: a chartered bank created to lend money to the state and issue notes.', 'Bank of England, ''Our history'' (the Bank was founded by Royal Charter in 1694); Clapham, J., The Bank of England: A History (1944).', null, false),
('banking', 1907, 'safekeeping', 'stability', array['trust']::driver[], 'incident', 'Panic of 1907: runs on New York trust companies and a near-collapse of the banking system.', 'Federal Reserve History, ''Panic of 1907''.', null, false),
('banking', 1907, 'lending', 'stability', array['trust']::driver[], 'protective_layer', 'A private rescue led by J. P. Morgan and the New York clearing house lent emergency funds to stop the panic.', 'Federal Reserve History, ''Panic of 1907''.', null, false),
('banking', 1913, 'rules and oversight', 'stability', array['government']::driver[], 'rule', 'Federal Reserve Act: created the US central bank as lender of last resort.', 'Federal Reserve History, ''Federal Reserve Act''.', null, false),
('banking', 1921, 'lending', 'growth', array['technology']::driver[], 'expansion', '1920s credit boom: the number of US banks peaked at roughly 30,000 and lending to stock buyers grew quickly.', 'Friedman, M. & Schwartz, A., A Monetary History of the United States, 1867-1960 (Princeton, 1963); exact peak year is approximate.', null, true),
('banking', 1929, 'safekeeping', 'stability', array['trust','growth']::driver[], 'incident', 'Stock market crash and a wave of bank failures through 1933.', 'Friedman, M. & Schwartz, A., A Monetary History of the United States, 1867-1960 (Princeton, 1963).', null, false),
('banking', 1933, 'safekeeping', 'trust', array['stability']::driver[], 'protective_layer', 'National bank holiday and Emergency Banking Act: banks closed, inspected, then reopened.', 'Federal Reserve History, ''Bank Holiday of 1933''.', null, false),
('banking', 1933, 'rules and oversight', 'trust', array['stability','government']::driver[], 'rule', 'Banking Act of 1933 (Glass-Steagall): deposit insurance (FDIC) and separation of commercial and investment banking.', 'Federal Reserve History, ''Banking Act of 1933, Glass-Steagall''.', null, false),
('banking', 2008, 'lending', 'stability', array['trust','growth']::driver[], 'incident', 'Global financial crisis: Lehman Brothers failed and credit markets froze.', 'Financial Crisis Inquiry Commission, Final Report (2011).', null, false),
('banking', 2008, 'safekeeping', 'stability', array['government']::driver[], 'protective_layer', 'Troubled Asset Relief Program (TARP): government capital injections into banks.', 'Emergency Economic Stabilization Act of 2008 (Public Law 110-343), US Treasury.', null, false),
('banking', 2009, 'moving value', 'technology', array['trust']::driver[], 'expansion', 'Bitcoin network launched: a way to move value without a bank in the middle.', 'Nakamoto, S., ''Bitcoin: A Peer-to-Peer Electronic Cash System'' (2008); first block mined January 2009.', null, false),
('banking', 2010, 'rules and oversight', 'stability', array['trust','government']::driver[], 'rule', 'Dodd-Frank Act: new bank capital rules, a consumer protection bureau and resolution powers.', 'Dodd-Frank Wall Street Reform and Consumer Protection Act, Public Law 111-203 (2010).', null, false),
('telephone service', 1876, 'connecting callers', 'technology', array['growth']::driver[], 'expansion', 'Telephone invented and patented by Alexander Graham Bell.', 'US Patent No. 174,465 (Bell, 1876).', null, false),
('telephone service', 1894, 'connecting callers', 'growth', array['technology']::driver[], 'expansion', 'Bell''s key patents expired and thousands of independent local telephone companies started.', 'Brooks, J., Telephone: The First Hundred Years (Harper & Row, 1976); exact year of the surge is approximate.', null, true),
