('telephone service', 1913, 'switching and routing', 'government', array['growth']::driver[], 'protective_layer', 'Kingsbury Commitment: AT&T agreed to let independents connect to its network after antitrust pressure.', 'Brooks, J., Telephone: The First Hundred Years (Harper & Row, 1976).', null, false),
