('telephone service', 2021, 'trust and privacy', 'security', array['technology','trust']::driver[], 'protective_layer', 'STIR/SHAKEN call-authentication technology required on major carrier networks.', 'FCC, ''Combating Spoofed Robocalls with Caller ID Authentication''; June 30, 2021 deadline for large providers.', null, false),
('electricity', 1882, 'generating power', 'technology', array['growth']::driver[], 'expansion', 'Edison''s Pearl Street Station in New York began supplying electricity to customers.', 'Hughes, T. P., Networks of Power: Electrification in Western Society, 1880-1930 (Johns Hopkins, 1983).', null, false),
